using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a post by its numeric ID from the API.")]
    public async Task<string> GetPost(
        [Description("The numeric post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpClientFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<Post>($"/posts/{id}", cancellationToken);
        return $"Title: {post?.Title}\n\n{post?.Body}";
    }

    [McpServerTool, Description("List all posts by a specific user ID.")]
    public async Task<string> GetPostsByUser(
        [Description("The user ID to filter posts by")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching posts for user {UserId}", userId);
        var client = httpClientFactory.CreateClient("api");
        var posts = await client.GetFromJsonAsync<Post[]>(
            $"/posts?userId={userId}", cancellationToken);

        if (posts is null || posts.Length == 0)
            return "No posts found for that user.";

        return string.Join("\n---\n", posts.Select(p => $"[{p.Id}] {p.Title}"));
    }

    [McpServerTool, Description("Get all comments on a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to get comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching comments for post {PostId}", postId);
        var client = httpClientFactory.CreateClient("api");
        var comments = await client.GetFromJsonAsync<Comment[]>(
            $"/posts/{postId}/comments", cancellationToken);

        if (comments is null || comments.Length == 0)
            return "No comments found.";

        return string.Join("\n---\n",
            comments.Select(c => $"{c.Name} ({c.Email}):\n{c.Body}"));
    }
}

public record Post(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("userId")] int UserId,
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("body")] string Body);

public record Comment(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("email")] string Email,
    [property: JsonPropertyName("body")] string Body);

